import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import "./manageUserAccounts.css";
import AdminSidebar from "../components/AdminSideBar";
import Navbar from "../components/navbar";
import Footer from "../components/footer";

function ManageUserAccounts() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [role, setRole] = useState("");
  const [registrationNumber, setRegistrationNumber] = useState("");
  const [password, setPassword] = useState("");

  const [students, setStudents] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [evaluators, setEvaluators] = useState([]);

  const [editingIndex, setEditingIndex] = useState(null);
  const [editingUserId, setEditingUserId] = useState(null);
  const [editingType, setEditingType] = useState("");

  const BASE_URL = "http://localhost:5000/api";

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    const [userRes, studentRes, evalRes, faRes] = await Promise.all([
      axios.get(`${BASE_URL}/user`),
      axios.get(`${BASE_URL}/student`),
      axios.get(`${BASE_URL}/evaluator`),
      axios.get(`${BASE_URL}/facultyadvisor`),
    ]);

    const users = userRes.data;

    setStudents(
      users
        .filter((u) => u.role === "Student")
        .map((u) => ({
          ...u,
          registrationNumber: studentRes.data.find((s) => s.userId === u._id)
            ?.regNo,
        }))
    );
    setSupervisors(
      users
        .filter((u) => u.role === "Supervisor")
        .map((u) => ({
          ...u,
          name:
            faRes.data.find((f) => f.userId === u._id)?.Name || u.username,
        }))
    );
    setEvaluators(
      users
        .filter((u) => u.role === "Evaluator")
        .map((u) => ({
          ...u,
          name:
            evalRes.data.find((e) => e.userId === u._id)?.name || u.username,
        }))
    );
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const userPayload = {
      username: name,
      email,
      password,
      role,
    };

    try {
      let userRes;
      if (editingUserId) {
        userRes = await axios.patch(`${BASE_URL}/user/${editingUserId}`, userPayload);
      } else {
        userRes = await axios.post(`${BASE_URL}/user`, userPayload);
      }

      const userId = userRes.data._id;

      // Create or update role-specific document
      if (role === "Student") {
        const studentPayload = {
          userId,
          studentName: name,
          regNo: registrationNumber,
          isGrouped: false,
        };
        await axios.post(`${BASE_URL}/student`, studentPayload);
      } else if (role === "Supervisor") {
        const supervisorPayload = {
          userId,
          Name: name,
          Meetings: [],
        };
        await axios.post(`${BASE_URL}/facultyadvisor`, supervisorPayload);
      } else if (role === "Evaluator") {
        const evaluatorPayload = {
          userId,
          name,
        };
        await axios.post(`${BASE_URL}/evaluator`, evaluatorPayload);
      }

      setName("");
      setEmail("");
      setPassword("");
      setRole("");
      setRegistrationNumber("");
      setEditingIndex(null);
      setEditingUserId(null);
      setEditingType("");

      fetchUsers();
    } catch (error) {
      alert("Error saving user.");
      console.error(error);
    }
  };

  const handleEdit = (index, type) => {
    const user =
      type === "student"
        ? students[index]
        : type === "supervisor"
        ? supervisors[index]
        : evaluators[index];

    setEditingIndex(index);
    setEditingType(type);
    setEditingUserId(user._id);
    setName(user.name || user.username);
    setEmail(user.email);
    setRole(user.role);
    setPassword(user.password || "");
    setRegistrationNumber(user.registrationNumber || "");
  };

  const handleDelete = async (userId, role) => {
    try {
      await axios.delete(`${BASE_URL}/user/${userId}`);
      if (role === "Student") {
        await axios.delete(`${BASE_URL}/student/${userId}`);
      } else if (role === "Supervisor") {
        await axios.delete(`${BASE_URL}/facultyadvisor/${userId}`);
      } else if (role === "Evaluator") {
        await axios.delete(`${BASE_URL}/evaluator/${userId}`);
      }
      fetchUsers();
    } catch (err) {
      alert("Error deleting user");
      console.error(err);
    }
  };

  const handleResetPassword = async (userId) => {
    const newPass = prompt("Enter new password:");
    if (newPass) {
      try {
        await axios.patch(`${BASE_URL}/user/reset-password/${userId}`, {
          password: newPass,
        });
        alert("Password updated.");
      } catch (err) {
        alert("Password reset failed.");
        console.error(err);
      }
    }
  };

  const renderTable = (users, type) => (
    <table>
      <thead>
        <tr>
          <th>Name</th>
          <th>Email</th>
          <th>Role</th>
          {type === "student" && <th>Registration Number</th>}
          <th>Actions</th>
        </tr>
      </thead>
      <tbody>
        {users.map((user, index) => (
          <tr key={user._id}>
            <td>{user.name || user.username}</td>
            <td>{user.email}</td>
            <td>{user.role}</td>
            {type === "student" && <td>{user.registrationNumber}</td>}
            <td>
              <button onClick={() => handleEdit(index, type)}>Edit</button>
              <button onClick={() => handleResetPassword(user._id)}>Reset Password</button>
              <button onClick={() => handleDelete(user._id, user.role)}>Delete</button>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );

  return (
    <div className="manage-user-accounts">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />
        <div className="main-content">
          <h1>Manage User Accounts</h1>
          <form onSubmit={handleSubmit} className="user-form">
            <label htmlFor="name">Name</label>
            <input value={name} onChange={(e) => setName(e.target.value)} required />

            <label htmlFor="email">Email</label>
            <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required />

            <label htmlFor="password">Password</label>
            <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} required={!editingUserId} />

            <label htmlFor="role">Role</label>
            <select value={role} onChange={(e) => setRole(e.target.value)} required>
              <option value="">Select Role</option>
              <option value="Student">Student</option>
              <option value="Supervisor">Supervisor</option>
              <option value="Evaluator">Evaluator</option>
            </select>

            {role === "Student" && (
              <>
                <label htmlFor="registrationNumber">Registration Number</label>
                <input value={registrationNumber} onChange={(e) => setRegistrationNumber(e.target.value)} required />
              </>
            )}

            {role === "Evaluator" && (
              <>
                <label htmlFor="registrationNumber">Registration Number</label>
                <input disabled placeholder="Not applicable" />
              </>
            )}

            <button type="submit" className="submit-btn">
              {editingIndex !== null ? "Update" : "Submit"}
            </button>
          </form>

          {students.length > 0 && (
            <>
              <h2>Student List</h2>
              {renderTable(students, "student")}
            </>
          )}

          {supervisors.length > 0 && (
            <>
              <h2>Supervisor List</h2>
              {renderTable(supervisors, "supervisor")}
            </>
          )}

          {evaluators.length > 0 && (
            <>
              <h2>Evaluator List</h2>
              {renderTable(evaluators, "evaluator")}
            </>
          )}
        </div>
      </div>
      <Footer />
    </div>
  );
}

